        You are a programming expert. 
        You will be provided with a patch used to fix a bug. 
        Based on the commit message and modifications in the patch, you need to analyze the root cause of the bug in detail. 

        Here is the patch content:
        From 120b270377aef4836c2cc46cd6dc69fdc714cebd Mon Sep 17 00:00:00 2001
From: Jeremy Mikola <jmikola@gmail.com>
Date: Mon, 12 Dec 2016 19:20:38 -0500
Subject: [PATCH] PHPC-851: Separate argument zvals before modification

This primarily fixes a bug introduced in 6d46d625770c56da4822ef4e4c7fb222f36703e2 for PHPC-359, since we convert tag sets from arrays to objects to ensure proper BSON serialization. Not only was the array mutation visible to calling contexts, but a crash could occur if the array was immutable due to OPcache.

For Manager's $driverOptions, a comment in 1060cb8ba4202461ef57fde3ab768fe790acb056 for PHPC-433 indicated that we should have separated its zval due to possible modification, but the appropriate zend_parse_parameters() flag was never used.
---
 php_phongo.c                          |  3 ++
 src/MongoDB/Manager.c                 | 10 +++--
 src/MongoDB/ReadPreference.c          |  4 +-
 tests/manager/bug0851-001.phpt        | 55 +++++++++++++++++++++++++++
 tests/manager/bug0851-002.phpt        | 28 ++++++++++++++
 tests/readPreference/bug0851-001.phpt | 47 +++++++++++++++++++++++
 6 files changed, 143 insertions(+), 4 deletions(-)
 create mode 100644 tests/manager/bug0851-001.phpt
 create mode 100644 tests/manager/bug0851-002.phpt
 create mode 100644 tests/readPreference/bug0851-001.phpt

diff --git a/php_phongo.c b/php_phongo.c
index 1e665ba6..443bcb04 100644
--- a/php_phongo.c
+++ b/php_phongo.c
@@ -837,7 +837,9 @@ void php_phongo_read_preference_prep_tagsets(zval *tagSets TSRMLS_DC) /* {{{ */
 		zval *tagSet;

 		ZEND_HASH_FOREACH_VAL(ht_data, tagSet) {
+			ZVAL_DEREF(tagSet);
 			if (Z_TYPE_P(tagSet) == IS_ARRAY) {
+				SEPARATE_ZVAL_NOREF(tagSet);
 				convert_to_object(tagSet);
 			}
 		} ZEND_HASH_FOREACH_END();
@@ -851,6 +853,7 @@ void php_phongo_read_preference_prep_tagsets(zval *tagSets TSRMLS_DC) /* {{{ */
 		     zend_hash_get_current_data_ex(ht_data, (void **) &tagSet, &pos) == SUCCESS;
 		     zend_hash_move_forward_ex(ht_data, &pos)) {
 			if (Z_TYPE_PP(tagSet) == IS_ARRAY) {
+				SEPARATE_ZVAL_IF_NOT_REF(tagSet);
 				convert_to_object(*tagSet);
 			}
 		}
diff --git a/src/MongoDB/Manager.c b/src/MongoDB/Manager.c
index 1d9251d6..7730c8fe 100644
--- a/src/MongoDB/Manager.c
+++ b/src/MongoDB/Manager.c
@@ -129,6 +129,8 @@ static void php_phongo_manager_prep_tagsets(zval *options TSRMLS_DC)
 			/* php_phongo_make_uri() and php_phongo_apply_rp_options_to_uri()
 			 * are both case-insensitive, so we need to be as well. */
 			if (!strcasecmp(ZSTR_VAL(string_key), "readpreferencetags")) {
+				ZVAL_DEREF(tagSets);
+				SEPARATE_ZVAL_NOREF(tagSets);
 				php_phongo_read_preference_prep_tagsets(tagSets TSRMLS_CC);
 			}
 		} ZEND_HASH_FOREACH_END();
@@ -152,6 +154,7 @@ static void php_phongo_manager_prep_tagsets(zval *options TSRMLS_DC)
 			/* php_phongo_make_uri() and php_phongo_apply_rp_options_to_uri()
 			 * are both case-insensitive, so we need to be as well. */
 			if (!strcasecmp(string_key, "readpreferencetags")) {
+				SEPARATE_ZVAL_IF_NOT_REF(tagSets);
 				php_phongo_read_preference_prep_tagsets(*tagSets TSRMLS_CC);
 			}
 		}
@@ -177,9 +180,10 @@ PHP_METHOD(Manager, __construct)
 	zend_replace_error_handling(EH_THROW, phongo_exception_from_phongo_domain(PHONGO_ERROR_INVALID_ARGUMENT), &error_handling TSRMLS_CC);
 	intern = Z_MANAGER_OBJ_P(getThis());

-	/* Separate the driverOptions zval, since we may end up modifying it in
-	 * php_phongo_manager_merge_context_options() below. */
-	if (zend_parse_parameters(ZEND_NUM_ARGS() TSRMLS_CC, "|s!a!a!", &uri_string, &uri_string_len, &options, &driverOptions) == FAILURE) {
+	/* Separate the options and driverOptions zvals, since we may end up
+	 * modifying them in php_phongo_manager_prep_tagsets() and
+	 * php_phongo_manager_merge_context_options() below, respectively. */
+	if (zend_parse_parameters(ZEND_NUM_ARGS() TSRMLS_CC, "|s!a/!a/!", &uri_string, &uri_string_len, &options, &driverOptions) == FAILURE) {
 		zend_restore_error_handling(&error_handling TSRMLS_CC);
 		return;
 	}
diff --git a/src/MongoDB/ReadPreference.c b/src/MongoDB/ReadPreference.c
index 419c2860..f6ff66b6 100644
--- a/src/MongoDB/ReadPreference.c
+++ b/src/MongoDB/ReadPreference.c
@@ -63,7 +63,9 @@ PHP_METHOD(ReadPreference, __construct)
 	zend_replace_error_handling(EH_THROW, phongo_exception_from_phongo_domain(PHONGO_ERROR_INVALID_ARGUMENT), &error_handling TSRMLS_CC);
 	intern = Z_READPREFERENCE_OBJ_P(getThis());

-	if (zend_parse_parameters(ZEND_NUM_ARGS() TSRMLS_CC, "l|a!a!", &mode, &tagSets, &options) == FAILURE) {
+	/* Separate the tagSets zval, since we may end up modifying it in
+	 * php_phongo_read_preference_prep_tagsets() below. */
+	if (zend_parse_parameters(ZEND_NUM_ARGS() TSRMLS_CC, "l|a/!a!", &mode, &tagSets, &options) == FAILURE) {
 		zend_restore_error_handling(&error_handling TSRMLS_CC);
 		return;
 	}
